import {LABS} from './modules/labs.mjs';
import {CATEGORIES,FA_TITLES,SHORT,CONTROLS,SOURCE_COMMIT,defaults,evaluate,sample,evidence,verifyEvidence,seeded,trainBorn,optimizeCut} from './modules/experiments.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='quantum001.studio.v1';
function readStored(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')??{};}catch{return {};}}
const stored=readStored();
let lang=stored.lang==='fa'?'fa':'en',entries=Array.isArray(stored.entries)?stored.entries.filter(e=>e?.payload?.schema==='quantum001.browser-experiment/v1').slice(0,12):[],visited=new Set(Array.isArray(stored.visited)?stored.visited:[]),filter='All',params={},activeId='',result=null,counts=null,tab='probabilities',animationStop=()=>{},paused=false,shots=512,seed=Math.floor(Math.random()*0xffffffff),lockSeed=false,toastTimer,trainingHistory=[];
const t=(en,fa)=>lang==='fa'?fa:en;
function persist(){try{localStorage.setItem(STORE,JSON.stringify({lang,entries,visited:[...visited]}));return true;}catch{toast(t('Your browser could not save this. Download the JSON to keep it.','ذخیره در مرورگر ممکن نشد؛ فایل JSON را دانلود کن.'));return false;}}
const ICONS={atom:'<ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(-40 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(40 12 12)"/><ellipse cx="12" cy="12" rx="4" ry="10"/><circle cx="12" cy="12" r="1.5" fill="currentColor" stroke="none"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',flask:'<path d="M9 3h6m-5 0v6l-6 10a1.5 1.5 0 0 0 1.3 2h13.4a1.5 1.5 0 0 0 1.3-2L14 9V3M7 15h10"/>',shield:'<path d="M12 3 3.5 6v6c0 5 8.5 9 8.5 9s8.5-4 8.5-9V6Z"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3ZM12 6v15"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',chevron:'<path d="m9 5 7 7-7 7"/>',github:'<path d="M9 19c-4 1-4-2-6-2m12 5v-4a3.3 3.3 0 0 0-.9-2.6c3-.3 6.2-1.5 6.2-6.8A5.3 5.3 0 0 0 19 5a5 5 0 0 0-.1-3s-1.1-.4-3.6 1.4a12 12 0 0 0-6.6 0C6.2 1.6 5.1 2 5.1 2A5 5 0 0 0 5 5a5.3 5.3 0 0 0-1.3 3.6c0 5.3 3.2 6.5 6.2 6.8A3.3 3.3 0 0 0 9 18v4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',play:'<path d="m8 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',refresh:'<path d="M20 10a8 8 0 0 0-14-5L3 8m0-5v5h5m-4 6a8 8 0 0 0 14 5l3-3m0 5v-5h-5"/>',terminal:'<path d="m4 5 6 7-6 7m9 0h7"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',check:'<path d="m5 12 4 4L19 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.atom}</svg>`;
const nameOf=id=>id==='composer'?t('Circuit Composer',FA_TITLES.composer):lang==='fa'?FA_TITLES[id]:LABS.find(l=>l.id===id)?.title??id;
const labelOf=key=>({Foundations:t('Foundations','مبانی'),Algorithms:t('Algorithms','الگوریتم‌ها'),'Noise & resilience':t('Noise & resilience','نویز و تاب‌آوری'),Learning:t('Learning','یادگیری'),All:t('All labs','همه')})[key]??key;
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setRoute(path){if(location.hash==='#'+path)render();else location.hash=path;}
function route(){return(location.hash.slice(1)||'overview').split('/');}
function nav(path,ico,text,extra='',compact=false){const [view,id]=route(),active=(path===view)||(path===`lab/${id}`);return `<a class="nav-link ${compact?'compact':''} ${active?'active':''}" href="#${path}">${ico}${text}${extra}</a>`;}
function chrome(){document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';const [view,id]=route();
 $('#sidebar').innerHTML=`<a class="brand" href="#overview" aria-label="Quantum001 home"><span class="brand-mark">${icon('atom')}</span><span class="wordmark">QUANTUM<b>001</b><span class="brand-sub">THE QUANTUM STUDIO</span></span></a><div class="side-label">${t('WORKSPACE','فضای پژوهش')}</div><nav>${nav('overview',icon('overview'),t('Overview','نمای کلی'))}${nav('library',icon('flask'),t('Research labs','آزمایشگاه‌ها'),'<small>12</small>')}${nav('composer',icon('atom'),t('Circuit composer','ساخت مدار'))}${nav('evidence',icon('shield'),t('Evidence vault','گنجینهٔ شواهد'),entries.length?`<small>${entries.length}</small>`:'')}${nav('notes',icon('book'),t('Field notes','یادداشت‌های پژوهش'))}</nav><div class="side-label">${t('START EXPLORING','مسیرهای پیشنهادی')}</div><nav>${['evolution','grover','qml','qec'].map(id=>nav('lab/'+id,`<span class="chapter">${LABS.find(x=>x.id===id).chapter}</span>`,nameOf(id),'',true)).join('')}</nav><a class="source-link" href="#library">${t('Explore all 12 labs','مشاهدهٔ هر ۱۲ آزمایش')} ${icon('arrow')}</a><div class="sidebar-spacer"></div><div class="engine-card"><strong><span class="dot"></span> &nbsp;${t('Local quantum engine','موتور کوانتومی محلی')}</strong><p>${t('Your browser. Your experiments.','مرورگر تو؛ آزمایش‌های تو.')}</p><div class="mini-wave" aria-hidden="true">${[5,9,13,7,18,10,14,6,12,17,10,4,8,12,6,15,9,5,11,8,4,6].map(x=>`<i style="height:${x}px"></i>`).join('')}</div></div><a class="source-link" href="https://github.com/aixaria0/Quantum001" target="_blank" rel="noopener">${icon('github')} ${t('Open source on GitHub','کد منبع در گیت‌هاب')} ${icon('up')}</a>`;
 const title=view==='lab'?nameOf(id):({overview:t('Overview','نمای کلی'),library:t('Research labs','آزمایشگاه‌ها'),composer:nameOf('composer'),evidence:t('Evidence vault','گنجینهٔ شواهد'),notes:t('Field notes','یادداشت‌های پژوهش')})[view]??t('Not found','پیدا نشد');
 $('#topbar').innerHTML=`<button class="icon-button mobile-menu" id="menu-toggle" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Studio</span>${icon('chevron')}<strong>${title}</strong></div><div class="topbar-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>${t('Search anything','جست‌وجو')}</span><kbd class="key">⌘ K</kbd></button><span class="status-inline"><span class="dot"></span>${t('ALL SYSTEMS LOCAL','اجرای کاملاً محلی')}</span><button class="language" data-action="language" aria-label="${lang==='en'?'Switch to Persian':'Switch to English'}">${lang==='en'?'فا / EN':'EN / فا'}</button></div>`;
 $('#footer').innerHTML=`<div class="footer"><span>${icon('atom')} QUANTUM001 <span>·</span> ${t('A studio for curious minds.','استودیویی برای ذهن‌های کنجکاو.')}</span><span>${t('Built by AIX Aria','ساختهٔ AIX Aria')} <span>·</span> <a href="https://github.com/aixaria0/Quantum001" target="_blank" rel="noopener">${t('Explore the source','مشاهدهٔ کد منبع')} ↗</a></span></div>`;
}

function miniArt(id){const j=LABS.findIndex(l=>l.id===id),s=seeded(j+19);let content='';
 if(['qml','qaoa','qec','atlas'].includes(id)){const pts=Array.from({length:7},(_,i)=>[25+90*s(),8+45*s()]);content=pts.map(([x,y],i)=>`${i?`<line x1="${pts[i-1][0]}" y1="${pts[i-1][1]}" x2="${x}" y2="${y}" stroke="currentColor" opacity=".25"/>`:''}<circle cx="${x}" cy="${y}" r="${i%3===0?3.5:2.3}" fill="${i%2?'currentColor':'var(--surface)'}" stroke="currentColor" opacity="${.4+i*.08}"/>`).join('');}
 else if(['grover','shor','qbm','advantage'].includes(id)){content=Array.from({length:15},(_,i)=>{const h=id==='grover'?(i===9?46:7+s()*5):7+s()*37;return `<rect x="${8+i*8}" y="${58-h}" width="4" height="${h}" rx="1" fill="currentColor" opacity="${i%3===0?.85:.25}"/>`;}).join('');}
 else{for(let k=0;k<3;k++){const points=Array.from({length:60},(_,i)=>`${i*2.25},${31+Math.sin(i*.14+k*1.1)*(16-k*3)}`).join(' ');content+=`<polyline points="${points}" fill="none" stroke="currentColor" stroke-width="1" opacity="${.7-k*.2}"/>`;}}
 return `<svg viewBox="0 0 140 68" aria-hidden="true">${content}</svg>`;
}
function labCards(all=true){const labs=LABS.filter(l=>filter==='All'||CATEGORIES[l.id]===filter).slice(0,all?12:6);return labs.map(l=>`<a href="#lab/${l.id}" class="lab-card"><div class="lab-card-art"><span class="card-no">EXP. ${l.chapter}</span>${miniArt(l.id)}</div><div class="lab-card-body"><span class="card-category">${labelOf(CATEGORIES[l.id])}</span><h3>${nameOf(l.id)}</h3><p>${SHORT[l.id][lang==='fa'?1:0]}</p><div class="lab-card-bottom"><span class="${visited.has(l.id)?'done-indicator':''}">${visited.has(l.id)?t('Explored','دیده‌شده'):t('Interactive experiment','آزمایش تعاملی')}</span>${icon('arrow')}</div></div></a>`).join('');}
function filters(){return `<div class="filters" role="group" aria-label="Filter research labs">${['All','Foundations','Algorithms','Noise & resilience','Learning'].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${labelOf(x)}</button>`).join('')}</div>`;}
function overview(library=false){return `<div class="screen-enter">${library?`<div class="notes-intro"><div class="eyebrow">THE RESEARCH COLLECTION</div><h1>${t('Twelve doors. A new way to think.','دوازده در؛ راهی تازه برای اندیشیدن.')}</h1><p>${t('Follow a thread, change a parameter, see what happens. Every idea here is something you can explore.','یک مسیر را دنبال کن، پارامترها را تغییر بده و نتیجه را ببین. اینجا هر ایده قابل تجربه است.')}</p></div>`:`<div class="page-heading"><div><h1>${t('Your quantum workspace.','فضای پژوهش کوانتومی تو.')}</h1><p>${t('A good day to question what’s possible.','روز خوبی برای کشف امکان‌های تازه است.')}</p></div><a class="btn secondary small" href="#notes">${icon('book')}${t('Read the field notes','یادداشت‌ها')}</a></div><section class="hero"><div class="hero-copy"><div class="eyebrow">${t('COMPUTATION. WITH CURIOSITY.','محاسبه، با چاشنی کنجکاوی.')}</div><h2>${t('A little uncertainty.<br><em>Endless possibility.</em>','کمی عدم‌قطعیت.<br><em>امکان‌های بی‌پایان.</em>')}</h2><p>${t('Step inside quantum computing. Shape a state, explore an algorithm, and turn abstract ideas into experiments you can see.','به دنیای محاسبات کوانتومی قدم بگذار. حالت بساز، الگوریتم‌ها را تجربه کن و ایده‌های انتزاعی را به آزمایش‌های دیدنی تبدیل کن.')}</p><div class="hero-buttons"><a href="#lab/evolution" class="btn">${icon('play')}${t('Start exploring','شروع اکتشاف')}</a><a href="#composer" class="btn ghost">${t('Build a circuit','یک مدار بساز')} ${icon('arrow')}</a></div><div class="hero-foot"><span><span class="dot"></span>${t('REAL CALCULATIONS','محاسبهٔ واقعی')}</span><span>↳ ${t('NO SETUP REQUIRED','بدون نیاز به نصب')}</span></div></div><div class="hero-art"><canvas id="hero-canvas" role="img" aria-label="Animated geometric quantum state illustration"></canvas><div class="art-top"><span>STATE SPACE / 001</span><span class="pill">|ψ⟩ = α|0⟩ + β|1⟩</span></div><span class="coordinates">SUPERPOSITION · EXPLORATION</span><div class="art-bottom"><span>${t('One state. Infinite questions.','یک حالت؛ بی‌نهایت پرسش.')}</span><button class="icon-button" data-action="pause" aria-label="Pause orbital animation" aria-pressed="false">${icon('pause')}</button></div></div></section><section class="stats-row" aria-label="Studio capabilities">${[['flask',t('RESEARCH LABS','آزمایشگاه‌ها'),'12',t('ideas to explore','مسیر پژوهش')],['layers',t('REGISTER CAPACITY','ظرفیت رجیستر'),'4,096',t('amplitudes · 12 qubits','دامنه · ۱۲ کیوبیت')],['shield',t('EVIDENCE INTEGRITY','یکپارچگی شواهد'),'SHA-256',t('inspectable records','سوابق قابل‌بررسی')],['chip',t('EXECUTION ENVIRONMENT','محیط اجرا'),'100%',t('in your browser','داخل مرورگر')]].map(([i,l,v,s])=>`<div class="stat"><div class="stat-top">${icon(i)}${l}</div><div class="stat-value">${v}<small>${s}</small></div></div>`).join('')}</section>`}<section><div class="section-heading"><div><h2>${library?t('Find your next question.','پرسش بعدی‌ات را پیدا کن.'):t('Choose your next experiment.','آزمایش بعدی‌ات را انتخاب کن.')}</h2><p>${t('Small experiments. Fundamental ideas.','آزمایش‌های کوچک؛ ایده‌های بنیادی.')}</p></div>${filters()}</div><div class="lab-grid" id="lab-grid">${labCards(library||filter!=='All')}</div>${!library&&filter==='All'?`<a href="#library" class="btn ghost" style="margin-top:16px">${t('Explore the complete collection','مشاهدهٔ مجموعهٔ کامل')} <span class="mono">12</span>${icon('arrow')}</a>`:''}</section>${!library?`<section class="zip-feature"><div class="zip-feature-copy"><div class="eyebrow">FROM THE CHIMERA WORKSPACE</div><h3>${t('Entangle. Run. Keep the evidence.','درهم‌تنیده کن. اجرا کن. شواهد را نگه دار.')}</h3><p>${t('Go from a Bell pair to a 12-qubit GHZ state. Add noise, sample measurements, and save a record you can inspect and replay.','از یک جفت بل تا حالت GHZ دوازده‌کیوبیتی. نویز اضافه کن، اندازه‌گیری کن و سابقه‌ای قابل بررسی و بازپخش ذخیره کن.')}</p><a href="#composer" class="btn secondary small">${t('Open circuit composer','ورود به ساخت مدار')}${icon('arrow')}</a></div><div class="zip-feature-art" role="img" aria-label="CHIMERA hybrid command lattice artwork supplied in the workspace"></div></section>`:''}</div>`;}

function field(c){let value=params[c.key],max=c.max;if(activeId==='grover'&&c.key==='marked')max=(1<<+params.qubits)-1;const id='param-'+c.key;return `<label class="control" for="${id}"><span class="control-label"><span>${esc(c.label)}</span>${c.type==='range'?`<output id="out-${c.key}" for="${id}">${c.step<1?Number(value).toFixed(2):value}</output>`:''}</span>${c.type==='select'?`<select id="${id}" data-param="${c.key}">${c.options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input id="${id}" data-param="${c.key}" type="range" min="${c.min}" max="${max}" step="${c.step}" value="${value}"><span class="control-range-labels"><span>${c.min}</span><span>${max}</span></span>`}</label>`;}
function metrics(r){return r.metrics.map(([l,v,type])=>`<div class="metric"><label>${esc(l)}</label><strong>${type==='prob'?(v*100).toFixed(1):type==='fixed'?v.toFixed(3):type==='int'?v.toLocaleString('en'):esc(v)}</strong>${type==='prob'?'<small>%</small>':type==='rad'?'<small>rad</small>':''}</div>`).join('');}
function experiment(id){activeId=id;params=defaults(id);trainingHistory=[];tab='probabilities';counts=null;result=evaluate(id,params,seed);visited.add(id);persist();const lab=LABS.find(l=>l.id===id),composer=id==='composer';
 return `<div class="screen-enter"><div class="lab-intro"><div><div class="eyebrow">${composer?'CHIMERA / CIRCUIT WORKSPACE':`${labelOf(CATEGORIES[id])} / EXPERIMENT ${lab.chapter}`}</div><h1>${nameOf(id)}<span class="accent">.</span></h1><p>${composer?t('Compose a state. Introduce uncertainty. Leave an inspectable trail.','یک حالت بساز. عدم‌قطعیت را وارد کن. ردپایی قابل بررسی ثبت کن.'):lang==='fa'?SHORT[id][1]:esc(lab.summary)}</p></div><div class="lab-actions"><button class="btn secondary small" data-action="reset">${icon('refresh')}${t('Reset','بازنشانی')}</button><button class="btn secondary small" data-action="save">${icon('shield')}${t('Save evidence','ثبت شواهد')}</button></div></div><div class="formula-band"><span>THE IDEA</span><code>${composer?'|GHZₙ⟩ = (|0⟩⊗ⁿ + |1⟩⊗ⁿ) / √2':esc(lab.formula)}</code></div><div class="workspace"><section class="panel controls-panel"><div class="panel-header"><h2>${icon('flask')}${t('Experiment parameters','پارامترهای آزمایش')}</h2><span class="pill">LOCAL</span></div><div class="panel-body"><div id="parameter-fields" style="display:contents">${CONTROLS[id].map(field).join('')}</div>${id==='qaoa'?`<button class="btn secondary full" data-action="optimize" style="margin-bottom:18px">${icon('spark')}${t('Find best angles','جست‌وجوی بهترین زاویه‌ها')}</button>`:''}${id==='qbm'?`<button class="btn secondary full" data-action="train" style="margin-bottom:18px">${icon('spark')}${t('Train · 45 gradient steps','آموزش · ۴۵ گام گرادیان')}</button><div id="training-loss" class="training-loss"></div>`:''}<div class="shots-seed"><label class="control"><span class="control-label">${t('Measurement shots','تعداد شات')}</span><select id="shots">${[128,512,2048,8192].map(n=>`<option ${shots===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="control"><span class="control-label">${t('Replay seed','بذر بازپخش')}</span><input type="number" id="seed" min="0" max="4294967295" value="${seed}"></label></div><label class="control-label"><span>${t('Lock seed for replay','قفل بذر برای بازپخش')}</span><input type="checkbox" id="lock-seed" ${lockSeed?'checked':''}></label><button class="btn full" data-action="run">${icon('play')}${t('Run experiment','اجرای آزمایش')}</button><p class="control-note">${t('Parameters update the exact model. Run samples a new measurement record. Lock the seed to reproduce it.','پارامترها مدل را به‌روز می‌کنند. اجرا، اندازه‌گیری تازه می‌گیرد. با قفل بذر نتیجه را بازتولید کن.')}</p></div></section><div class="result-stack"><section class="panel"><div class="panel-header"><h2>${icon('atom')}${t('State exploration','بررسی حالت')}</h2><span class="pill green"><span class="dot"></span>${t('Local simulation','شبیه‌سازی محلی')}</span></div><div class="visual-stage" id="visual-stage"></div><div class="metrics" id="metrics">${metrics(result)}</div></section><section class="panel"><div class="result-tabs" role="tablist" aria-label="Experiment results">${[['probabilities',t('Probabilities','احتمال‌ها')],['measurements',t('Measurements','اندازه‌گیری')],['code',t('Circuit / model','مدار و مدل')],['trace',t('Execution trace','ردیابی اجرا')]].map(([v,l])=>`<button role="tab" aria-selected="${tab===v}" class="result-tab ${tab===v?'active':''}" data-tab="${v}">${l}</button>`).join('')}</div><div class="tab-body" id="tab-body"></div></section></div></div><div class="scope" id="model-scope">${icon('info')}<span>${esc(result.note)}</span></div><section class="explain-card"><div><h3>${t('Change something. Notice the difference.','چیزی را تغییر بده؛ تفاوت را ببین.')}</h3><p>${explanation(id)}</p></div><div><h3>${t('Keep a trail you can inspect.','ردپایی قابل بررسی نگه دار.')}</h3><p>${t('Save the parameters, sampling seed, model and result in one JSON record. SHA-256 detects changes to that record. It does not prove the model or attest to quantum hardware.','پارامترها، بذر نمونه‌گیری، مدل و نتیجه در یک فایل JSON ثبت می‌شوند. SHA-256 تغییرات فایل را تشخیص می‌دهد؛ صحت مدل یا اجرای سخت‌افزاری را اثبات نمی‌کند.')}</p></div></section>${composer?terminalMarkup():''}<nav class="lab-pagination" aria-label="Related labs"><a href="#library">← ${t('All research labs','همهٔ آزمایشگاه‌ها')}</a><a href="#lab/${LABS[((LABS.findIndex(x=>x.id===id)+1)||0)%LABS.length].id}">${t('Next experiment','آزمایش بعدی')} ${icon('arrow')}</a></nav></div>`;
}
function explanation(id){return ({evolution:t('Try θ = π on the X or Y axis: |0⟩ becomes |1⟩. Z rotation only changes a phase, so the measurement probabilities stay the same.','چرخش π حول X یا Y، حالت صفر را به یک می‌برد. چرخش Z فقط فاز را تغییر می‌دهد.'),grover:t('Increase the amplification rounds one at a time. The marked state grows, peaks, then shrinks: quantum interference rewards the right stopping point.','دورها را یکی‌یکی افزایش بده. احتمال پاسخ ابتدا رشد می‌کند و سپس کاهش می‌یابد؛ توقف در زمان مناسب مهم است.'),shor:t('Try N = 15 and a = 2. The order is 4; the classical post-processing gives 3 × 5. A different base can produce an unhelpful order.','برای N=15 و a=2، دوره ۴ است و پس‌پردازش کلاسیک عوامل ۳ و ۵ را می‌دهد.'),qaoa:t('Move the cost and mixer angles, then find the best pair with a numerical sweep. The expected cut averages over every bitstring, not just the most likely one.','زاویه‌های هزینه و مخلوط‌کننده را تغییر بده. مقدار مورد انتظار میانگین وزن‌دار همهٔ رشته‌های بیتی است.'),knitting:t('At θ = 0 the state is separable. At π/4 it is a Bell pair. The Pauli coefficients describe which correlations survive the reconstruction.','در زاویهٔ صفر حالت جداپذیر است؛ در π/4 جفت بل می‌شود. ضرایب پائولی، همبستگی‌ها را بازسازی می‌کنند.'),annealing:t('At a higher anneal fraction, temperature falls and fewer uphill moves survive. Run with a fresh seed to see a different stochastic trajectory.','با افزایش سهم بازپخت، دما کاهش می‌یابد. با بذر تازه اجرا کن تا مسیر تصادفی متفاوتی ببینی.'),qec:t('Inject an X error on each of the three physical qubits. Each produces a distinct two-bit syndrome, which selects the correction.','خطای X را روی هر کیوبیت اعمال کن. هر خطا نشانگان دوبیتی متفاوتی می‌سازد و اصلاح مناسب را تعیین می‌کند.'),qml:t('Move the two input features. The heatmap shows overlap with every point in the reference grid: brighter cells represent more similar encoded states.','دو ویژگی ورودی را تغییر بده. خانه‌های روشن‌تر، هم‌پوشانی بیشتر با حالت ورودی دارند.'),qbm:t('Train the six angles against a fixed target. The KL divergence is evaluated after real circuit calculations; each accepted gradient step reduces the loss.','شش زاویه را برای تطبیق با توزیع هدف آموزش بده. هر گام گرادیان پذیرفته‌شده، خطای KL را کاهش می‌دهد.'),mesolve:t('Damping pulls the state toward |0⟩. Dephasing suppresses the X and Y components. Purity can first fall, then recover near the ground state.','میرایی حالت را به صفر نزدیک می‌کند. واهمدوسی مؤلفه‌های X و Y را کاهش می‌دهد. خلوص ممکن است دوباره افزایش یابد.'),advantage:t('Choose a problem family. Quadratic search scaling and exponential statevector memory are different claims; neither alone is a hardware benchmark.','خانوادهٔ مسئله را انتخاب کن. مقیاس جست‌وجو و حافظهٔ بردار حالت، ادعاهای متفاوت‌اند و بنچمارک سخت‌افزاری نیستند.'),atlas:t('Follow a family to its experiment. Begin with dynamics, then explore algorithms, learning and the effects of a noisy environment.','از تحول زمانی شروع کن؛ سپس الگوریتم‌ها، یادگیری و اثر محیط نویزی را تجربه کن.'),composer:t('Bell and GHZ states place ideal probability on all-zero and all-one outcomes. Turn up global depolarizing noise to mix in a uniform distribution.','حالت‌های بل و GHZ احتمال را میان خروجی تمام‌صفر و تمام‌یک تقسیم می‌کنند. نویز، توزیع یکنواخت را به آن می‌افزاید.')})[id];}

function bars(probs,asCounts=false){if(!probs)return `<p class="muted">${t('This experiment produces a model trace rather than a state histogram.','خروجی این آزمایش، رد مدل است و هیستوگرام ندارد.')}</p>`;const n=Math.log2(probs.length),all=probs.map((v,i)=>({v,i}));let arr=all.length>16?all.sort((a,b)=>b.v-a.v).slice(0,16).sort((a,b)=>a.i-b.i):all;const max=Math.max(...arr.map(x=>x.v),.0001);return `<div class="prob-chart" role="img" aria-label="${asCounts?'Sample counts':'Exact probabilities'}">${arr.map(({v,i})=>`<div class="prob-col" title="${i.toString(2).padStart(n,'0')}: ${asCounts?v:(v*100).toFixed(4)+'%'}"><i style="height:${v/max*100}%"></i><span>${n>6?i:i.toString(2).padStart(n,'0')}</span><b>${asCounts?v:(v*100).toFixed(1)+'%'}</b></div>`).join('')}</div><div class="chart-caption"><span>${asCounts?t('SAMPLED OUTCOMES','خروجی‌های نمونه‌گیری‌شده'):t('EXACT PROBABILITY MASS','توزیع احتمال مدل')}${all.length>16?` · ${t('TOP 16 STATES','۱۶ حالت برتر')}`:''}</span><span class="mono">${asCounts?'Σ = '+probs.reduce((a,b)=>a+b,0):'Σ P = '+probs.reduce((a,b)=>a+b,0).toFixed(6)}</span></div>`;}
function lineChart(history){if(!history?.length)return '';const vs=history.map(x=>x.value),min=Math.min(...vs),max=Math.max(...vs),span=max-min||1,points=vs.map((v,i)=>`${30+i/(vs.length-1||1)*460},${150-(v-min)/span*115}`).join(' ');return `<svg viewBox="0 0 520 190" role="img" aria-label="Execution trajectory"><path d="M30 20v132h470" fill="none" stroke="var(--line)"/><path d="M30 85h470M30 30h470" stroke="var(--line)" stroke-dasharray="3 5"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2"/><text x="30" y="180" fill="var(--faint)" font-size="9" font-family="monospace">0</text><text x="470" y="180" fill="var(--faint)" font-size="9" font-family="monospace">${esc(history.at(-1).t)}</text><text x="32" y="20" fill="var(--muted)" font-size="9" font-family="monospace">${max.toFixed(3)}</text></svg>`;}
function renderTab(){if(!result)return;$('#tab-body').innerHTML=tab==='probabilities'?(result.target?`<div class="comparison"><div><h3>TARGET DISTRIBUTION</h3>${bars(result.target)}</div><div><h3>BORN DISTRIBUTION</h3>${bars(result.probabilities)}</div></div>`:result.probabilities?bars(result.probabilities):result.history?lineChart(result.history):`<p class="muted">${esc(result.note)}</p>`):tab==='measurements'?(counts?bars(counts,true):`<div class="empty-state" style="margin:0;padding:26px"><p>${t('Run the experiment to sample a measurement record.','برای نمونه‌گیری، آزمایش را اجرا کن.')}</p><button class="btn small" data-action="run">${icon('play')}${t('Run now','اجرا')}</button></div>`):tab==='code'?`<pre>${esc(result.qasm??JSON.stringify({model:result.kind,parameters:params,scope:result.note},null,2))}</pre><button class="btn ghost small" data-action="export-code" style="margin-top:15px">${icon('download')}${result.qasm?'Export .qasm':'Export model .json'}</button>`:`<pre>${esc(JSON.stringify({experiment:result.id,model:result.kind,seed,shots:counts?shots:0,normalization:result.probabilities?result.probabilities.reduce((a,b)=>a+b,0):null,metrics:result.metrics,training_loss:trainingHistory.length?trainingHistory:undefined},null,2))}</pre>`;
 document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',String(b.dataset.tab===tab));b.tabIndex=b.dataset.tab===tab?0:-1;});}
function graphSvg(bits,edges,spins){const n=spins?.length??4,pts=Array.from({length:n},(_,i)=>[250+95*Math.cos(i*2*Math.PI/n-Math.PI/2),125+90*Math.sin(i*2*Math.PI/n-Math.PI/2)]),e=edges??pts.map((_,i)=>[i,(i+1)%n]);return `<svg viewBox="0 0 500 250" role="img" aria-label="${spins?'Spin ring':'MaxCut graph'}">${e.map(([a,b])=>`<line x1="${pts[a][0]}" y1="${pts[a][1]}" x2="${pts[b][0]}" y2="${pts[b][1]}" stroke="var(--accent)" opacity=".3" stroke-width="1.5"/>`).join('')}${pts.map(([x,y],i)=>{const v=spins?spins[i]>0:bits[n-1-i]==='1';return `<circle cx="${x}" cy="${y}" r="15" fill="${v?'var(--accent)':'var(--surface)'}" stroke="var(--accent)"/><text x="${x}" y="${y+3}" text-anchor="middle" fill="${v?'var(--bg)':'var(--accent)'}" font-size="10" font-family="monospace">${spins?(v?'↑':'↓'):'q'+i}</text>`;}).join('')}</svg>`;}
function drawResult(){animationStop();const stage=$('#visual-stage');if(!stage)return;
 if(result.bloch){stage.innerHTML=`<span class="stage-top">BLOCH SPHERE · q₀</span><canvas id="state-canvas" role="img" aria-label="Bloch vector of the simulated qubit"></canvas><span class="stage-bottom">x ${result.bloch.x.toFixed(3)} / y ${result.bloch.y.toFixed(3)} / z ${result.bloch.z.toFixed(3)}</span>`;animationStop=orbital($('#state-canvas'),result.bloch);}
 else if(result.graph||result.spins){stage.innerHTML=`<div class="stage-figure">${graphSvg(result.graph?.bits,result.graph?.edges,result.spins)}</div>`;}
 else if(result.heat){stage.innerHTML=`<div class="stage-figure"><svg viewBox="0 0 500 250" role="img" aria-label="Quantum feature kernel heatmap">${result.heat.flatMap((row,y)=>row.map((v,x)=>`<rect x="${122+x*13}" y="${8+y*13}" width="11" height="11" rx="1" fill="var(--accent)" opacity="${.05+.95*v}"/>`)).join('')}<text x="369" y="241" font-size="9" fill="var(--faint)">π</text><text x="96" y="14" font-size="9" fill="var(--faint)">π</text><text x="116" y="242" font-size="9" fill="var(--faint)">0</text></svg></div>`;}
 else if(result.syndrome){stage.innerHTML=`<div class="stage-figure"><svg viewBox="0 0 500 230" role="img" aria-label="Three qubit bit-flip correction circuit">${[0,1,2].map((q)=>`<text x="35" y="${65+55*q}" fill="var(--faint)" font-size="11" font-family="monospace">q${q}</text><line x1="75" y1="${61+55*q}" x2="455" y2="${61+55*q}" stroke="var(--line)"/><rect x="130" y="${43+55*q}" width="42" height="36" rx="6" fill="var(--raised)" stroke="var(--line)"/><text x="151" y="${66+55*q}" text-anchor="middle" fill="var(--muted)" font-size="10">ENC</text>${+params.error===q?`<rect x="240" y="${43+55*q}" width="38" height="36" rx="6" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="259" y="${66+55*q}" text-anchor="middle" fill="var(--accent)" font-size="14">X</text><rect x="345" y="${43+55*q}" width="38" height="36" rx="6" fill="var(--green-soft)" stroke="var(--green)"/><text x="364" y="${66+55*q}" text-anchor="middle" fill="var(--green)" font-size="14">X</text>`:''}`).join('')}<text x="245" y="215" fill="var(--faint)" font-size="9" font-family="monospace">INJECT</text><text x="340" y="215" fill="var(--faint)" font-size="9" font-family="monospace">CORRECT</text></svg></div>`;}
 else if(activeId==='atlas'){stage.innerHTML=`<div class="atlas-grid" style="width:100%">${[['Dynamics',['evolution','knitting','advantage']],['Algorithms',['shor','grover','qaoa','annealing']],['Learning & noise',['qml','qbm','qec','mesolve']]].map(([title,ids])=>`<div class="atlas-group"><h3>${title}</h3>${ids.map(id=>`<a href="#lab/${id}">${nameOf(id)} ↗</a>`).join('')}</div>`).join('')}</div>`;}
 else if(result.complexity){const {n,N,problem}=result.complexity;stage.innerHTML=`<div style="padding:25px;width:100%"><div class="eyebrow">${problem==='search'?'ORACLE QUERY SCALING':problem==='factoring'?'COMPLEXITY CLASSES':'EXACT STATE MEMORY'}</div><h2 style="font-weight:450;font-size:clamp(25px,3vw,38px);letter-spacing:-1px;margin:18px 0">${problem==='search'?`${N.toLocaleString()} → ${Math.sqrt(N).toFixed(0)}`:problem==='factoring'?'Sub-exponential → polynomial':`${(N*16/1024/1024).toFixed(2)} MiB`}</h2><p class="muted" style="font-size:11px">${problem==='search'?`O(N) classical queries → O(√N) quantum queries · N = 2^${n}`:problem==='factoring'?'Number field sieve vs. ideal fault-tolerant Shor scaling. Constants, error correction and physical resources are omitted.':`2^${n} complex128 amplitudes × 16 bytes. This is classical statevector storage, not quantum hardware memory.`}</p></div>`;}
 else if(result.terms){stage.innerHTML=`<div class="table-wrap" style="width:100%"><table><thead><tr><th>PAULI OBSERVABLE</th><th>DENSITY COEFFICIENT</th></tr></thead><tbody>${result.terms.map(([k,v])=>`<tr><td class="mono">${k}</td><td class="mono accent">${v.toFixed(4)}</td></tr>`).join('')}</tbody></table></div>`;}
 else if(activeId==='shor'){stage.innerHTML=`<div style="padding:30px;width:100%">${bars(result.probabilities)}<p class="muted" style="font-size:10px;margin-top:20px">Analytic Fourier readout · classically calculated order r = ${result.period}</p></div>`;}
 else if(activeId==='qbm'){stage.innerHTML=`<div class="stage-figure">${bornCircuit()}</div>`;}
 else if(result.history){stage.innerHTML=`<div class="stage-figure">${lineChart(result.history)}</div>`;}
 else{const n=result.qubits??Math.log2(result.probabilities?.length??4);stage.innerHTML=`<div class="stage-figure">${circuitSvg(n,activeId==='composer'?params.preset:'shor')}</div>`;}
 $('#metrics').innerHTML=metrics(result);$('#model-scope').innerHTML=icon('info')+`<span>${esc(result.note)}</span>`;renderTab();
}
function circuitSvg(n,preset){const rows=Math.min(n,5),ys=Array.from({length:rows},(_,i)=>38+i*43),last=ys.at(-1);return `<svg viewBox="0 0 520 ${Math.max(205,last+35)}" role="img" aria-label="${esc(preset)} circuit diagram">${ys.map((y,i)=>`<text x="32" y="${y+4}" fill="var(--faint)" font-family="monospace" font-size="10">q${i===4&&n>5?n-1:i} |0⟩</text><path d="M95 ${y}h383" stroke="var(--line)"/>${i===0&&preset!=='product'?`<rect x="125" y="${y-16}" width="32" height="32" rx="5" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="141" y="${y+5}" text-anchor="middle" fill="var(--accent)" font-size="13">H</text>`:''}${i>0&&preset!=='product'?`<line x1="${185+i*48}" y1="${ys[0]}" x2="${185+i*48}" y2="${y}" stroke="var(--accent)" opacity=".8"/><circle cx="${185+i*48}" cy="${ys[0]}" r="3" fill="var(--accent)"/><circle cx="${185+i*48}" cy="${y}" r="10" fill="var(--surface)" stroke="var(--accent)"/><path d="M${179+i*48} ${y}h12m-6-6v12" stroke="var(--accent)"/>`:''}<rect x="445" y="${y-12}" width="25" height="24" rx="4" fill="var(--raised)"/><path d="M450 ${y+5}a8 8 0 0 1 15 0m-8 0 5-10" fill="none" stroke="var(--muted)"/>`).join('')}${n>5?`<text x="100" y="${last+29}" fill="var(--faint)" font-size="9" font-family="monospace">⋯ ${n}-qubit register · intermediate wires omitted</text>`:''}</svg>`;}
function bornCircuit(){return `<svg viewBox="0 0 520 230" role="img" aria-label="Two layers of RY rotations and controlled Z gates">${[0,1,2].map((q)=>`<text x="30" y="${56+60*q}" fill="var(--faint)" font-size="11" font-family="monospace">q${q}</text><line x1="65" y1="${52+60*q}" x2="480" y2="${52+60*q}" stroke="var(--line)"/>${[0,1].map(layer=>`<rect x="${105+layer*200}" y="${35+60*q}" width="65" height="34" rx="5" fill="var(--accent-soft)" stroke="var(--accent)"/><text x="${137+layer*200}" y="${57+60*q}" text-anchor="middle" fill="var(--accent)" font-size="10">RY(${Number(params[(layer?'b':'a')+q]).toFixed(2)})</text>`).join('')}`).join('')}${[0,1].flatMap(layer=>[0,1].map(q=>`<path d="M${205+layer*200+q*30} ${52+60*q}v60" stroke="var(--green)"/><circle cx="${205+layer*200+q*30}" cy="${52+60*q}" r="4" fill="var(--green)"/><circle cx="${205+layer*200+q*30}" cy="${112+60*q}" r="4" fill="var(--green)"/>`)).join('')}<text x="135" y="220" fill="var(--faint)" font-size="9" font-family="monospace">LAYER 1 / RY + CZ</text><text x="335" y="220" fill="var(--faint)" font-size="9" font-family="monospace">LAYER 2 / RY + CZ</text></svg>`;}

function orbital(canvas,vector=null){let raf=0,stopped=false,last=0,rotation=0;const ctx=canvas.getContext('2d');if(!ctx)return()=>{};const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const project=(x,y,z,cx,cy,r,a)=>{const xr=x*Math.cos(a)+z*Math.sin(a),zr=-x*Math.sin(a)+z*Math.cos(a),yr=y*.89-zr*.46,zz=y*.46+zr*.89;return{x:cx+xr*r,y:cy-yr*r,z:zz};};
 function draw(now){if(stopped)return;raf=requestAnimationFrame(draw);if(document.hidden||now-last<32)return;last=now;const box=canvas.getBoundingClientRect();if(box.width===0)return;const dpr=Math.min(devicePixelRatio||1,2),w=box.width,h=box.height;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(!paused&&!reduce)rotation+=.003;const cx=w*.5,cy=h*.52,r=Math.min(w*.35,h*.39),a=rotation+.5;
 ctx.strokeStyle='#a58b5c25';ctx.lineWidth=.6;for(let k=1;k<6;k++){ctx.beginPath();ctx.arc(cx,cy,r+k*12,0,Math.PI*2);ctx.setLineDash(k===3?[1,9]:[]);ctx.stroke();}ctx.setLineDash([]);
 // The decorative hero is an orbital state-space illustration, not a measurement plot.
 for(let lat=-7;lat<=7;lat++){const theta=lat/8*Math.PI/2;ctx.beginPath();for(let i=0;i<=100;i++){const phi=i/100*Math.PI*2,p=project(Math.cos(theta)*Math.cos(phi),Math.sin(theta),Math.cos(theta)*Math.sin(phi),cx,cy,r,a);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);}ctx.strokeStyle=`rgba(211,155,91,${lat%2===0?.16:.08})`;ctx.stroke();}
 for(let lon=0;lon<22;lon++){ctx.beginPath();for(let i=0;i<=55;i++){const theta=-Math.PI/2+i/55*Math.PI,phi=lon/22*Math.PI*2,p=project(Math.cos(theta)*Math.cos(phi),Math.sin(theta),Math.cos(theta)*Math.sin(phi),cx,cy,r,a);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);}ctx.strokeStyle='rgba(211,155,91,.12)';ctx.stroke();}
 for(let i=0;i<560;i++){const phi=i*2.399963,yy=1-2*(i+.5)/560,rr=Math.sqrt(1-yy*yy),p=project(rr*Math.cos(phi),yy,rr*Math.sin(phi),cx,cy,r,a);ctx.fillStyle=`rgba(238,180,112,${.12+(p.z+1)*.2})`;ctx.beginPath();ctx.arc(p.x,p.y,p.z>.4?1:.6,0,Math.PI*2);ctx.fill();}
 for(let ring=0;ring<2;ring++){ctx.beginPath();for(let i=0;i<=150;i++){const th=i/150*Math.PI*2,rrr=1.23,ang=.42+ring*1.2,p=project(Math.cos(th)*rrr,Math.sin(th)*Math.sin(ang)*rrr,Math.sin(th)*Math.cos(ang)*rrr,cx,cy,r,a);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);}ctx.strokeStyle=ring?'#e9ac6d38':'#e9ac6d88';ctx.lineWidth=ring?.6:1;ctx.stroke();}
 const v=vector??{x:.62,y:.48,z:.62},p=project(v.x,v.z,v.y,cx,cy,r,a);ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(p.x,p.y);ctx.strokeStyle='#edba81';ctx.lineWidth=1.6;ctx.stroke();const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,14);g.addColorStop(0,'#ffd7a5c0');g.addColorStop(.3,'#e8a46b60');g.addColorStop(1,'#e8a46b00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,14,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffe0b3';ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9b69a';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('|0⟩',cx,cy-r-13);ctx.fillStyle='#737a68';ctx.fillText('|1⟩',cx,cy+r+20);ctx.fillText('−x',cx-r-16,cy+3);ctx.fillText('+x',cx+r+16,cy+3);ctx.beginPath();ctx.arc(cx,cy,2,0,Math.PI*2);ctx.fillStyle='#d7b986';ctx.fill();if(reduce){cancelAnimationFrame(raf);}}
 raf=requestAnimationFrame(draw);return()=>{stopped=true;cancelAnimationFrame(raf);};}

function terminalMarkup(){return `<section class="terminal"><div class="terminal-heading"><span class="terminal-dots"><i></i><i></i><i></i></span>Q001 / LOCAL COMMAND INTERFACE <span style="margin-left:auto">${t('type help','بنویس help')}</span></div><div class="terminal-output" id="terminal-output">Quantum001 local console. Commands execute the browser simulation.<br><span class="accent">› help</span><br>bell · ghz 4 · ghz 12 · product · noise 0.2 · help</div><form id="terminal-form" class="terminal-form"><span>›</span><input id="terminal-input" aria-label="Local quantum command" placeholder="ghz 12" autocomplete="off" spellcheck="false"><button class="btn secondary small" type="submit">↵</button></form></section>`;}
function vault(){return `<div class="screen-enter"><div class="vault-heading"><div class="eyebrow">YOUR RESEARCH TRAIL</div><h1>${t('A result worth keeping.','نتیجه‌ای که ارزش ثبت دارد.')}<span class="accent">.</span></h1><p>${t('Local experiments, bound to their inputs. Inspect the parameters, verify the record’s integrity, or replay a run. Records stay in this browser.','آزمایش‌های محلی، همراه با ورودی‌هایشان. پارامترها را ببین، یکپارچگی سابقه را بررسی کن یا اجرا را تکرار کن. سوابق در همین مرورگر می‌مانند.')}</p></div>${entries.length?`<div class="notice">${t('SHA-256 detects changes to the saved payload. It is an integrity check, not a formal proof, signature or quantum hardware attestation.','هش SHA-256 تغییرات داده را مشخص می‌کند؛ این بررسی، اثبات رسمی، امضا یا گواهی سخت‌افزار کوانتومی نیست.')}</div>${entries.map((e,i)=>`<article class="evidence-item"><div class="evidence-top"><div><h3>${nameOf(e.payload.experiment)} <span class="mono faint">/ ${String(entries.length-i).padStart(3,'0')}</span></h3><p>${esc(new Date(e.payload.created_at).toLocaleString(lang==='fa'?'fa-IR':'en-GB'))} · seed ${esc(e.payload.seed)} · ${e.payload.shots} shots</p></div><span class="pill green">${icon('shield')}SHA-256 BOUND</span></div><div class="evidence-bottom"><button class="btn secondary small" data-verify="${i}">${icon('check')}${t('Verify integrity','بررسی هش')}</button><button class="btn secondary small" data-replay="${i}">${icon('play')}${t('Replay','بازپخش')}</button><button class="btn secondary small" data-download="${i}">${icon('download')}JSON</button><button class="btn ghost small" data-remove="${i}" aria-label="Remove this saved record">${icon('trash')}</button></div><div class="digest">${esc(e.sha256)}</div></article>`).join('')}`:`<div class="empty-state">${icon('shield')}<h2>${t('Your next discovery belongs here.','کشف بعدی تو، جای‌اش اینجاست.')}</h2><p>${t('Open an experiment and choose Save evidence. Its settings, results and replay seed will appear here.','آزمایشی را باز کن و «ثبت شواهد» را بزن. تنظیمات، نتیجه و بذر بازپخش اینجا نمایش داده می‌شوند.')}</p><a class="btn" href="#composer">${icon('flask')}${t('Create your first record','نخستین سابقه را بساز')}</a></div>`}<div class="scope">${icon('info')}<span>${t('Keep up to 12 records locally. Download JSON files to keep a durable copy outside this browser.','تا ۱۲ سابقه در مرورگر نگه داشته می‌شود. برای نگه‌داری پایدار، JSON را دانلود کن.')}</span></div></div>`;}
function notes(){return `<div class="screen-enter"><div class="notes-intro"><div class="eyebrow">CONTEXT, NOT JUST COMPUTATION</div><h1>${t('The ideas behind the interface.','ایده‌های پشت این محیط.')}<span class="accent">.</span></h1><p>${t('A small field guide to what this studio calculates, where the source lives, and where its boundaries are.','راهنمایی کوتاه برای محاسبات این استودیو، منبع آن و مرزهای مدل‌ها.')}</p></div><div class="note-grid"><article class="note-card"><div class="note-no">01 / THE ORIGINAL ENGINE</div><h2>${t('Twelve experiments. One statevector.','دوازده آزمایش؛ یک بردار حالت.')}</h2><p>${t('The research collection is built around Quantum001’s QState engine: complex amplitudes, single-qubit rotations, controlled gates, quantum search, feature maps and variational circuits. The studio uses an unchanged JavaScript translation of that numerical engine.','مجموعهٔ پژوهشی بر موتور QState ریپو استوار است: دامنه‌های مختلط، چرخش‌ها، گیت‌های کنترل‌شده، جست‌وجو و مدارهای واریاسیونی. استودیو از ترجمهٔ جاوااسکریپت همان موتور عددی استفاده می‌کند.')}</p><p style="margin-top:18px"><a href="https://github.com/aixaria0/Quantum001/blob/${SOURCE_COMMIT}/src/lib/quantum/engine.ts" target="_blank" rel="noopener">Inspect the numerical source ↗</a></p><div class="digest">SOURCE COMMIT<br>${SOURCE_COMMIT}</div></article><article class="note-card"><div class="note-no">02 / THE CHIMERA WORKSPACE</div><h2>${t('From exploration to evidence.','از اکتشاف تا شواهد.')}</h2><p>${t('The supplied workspace adds a second thread: Bell and GHZ preparation, twelve-qubit registers, circuit inspection and a record of each execution. Its CHIMERA artwork is preserved here. The composer brings that thread into the same studio.','فضای کاری پیوست، مسیر دومی می‌آورد: حالت‌های بل و GHZ، رجیستر دوازده‌کیوبیتی، بررسی مدار و ثبت اجرا. تصویر CHIMERA از همان فایل حفظ شده است.')}</p><p style="margin-top:18px">${t('The workspace’s illustrative HotStuff rounds and Lean sketches are source material, not a live consensus network or a checked proof.','دورهای نمایشی HotStuff و طرح‌های Lean در ZIP، شبکهٔ اجماع زنده یا اثبات بررسی‌شده نیستند.')}</p><a class="btn secondary small" style="margin-top:20px" href="#composer">${t('Explore the composer','ساخت مدار')}${icon('arrow')}</a></article><article class="note-card note-full"><img class="note-image" src="./assets/chimera-lattice.jpg" alt="Original CHIMERA hybrid command lattice artwork from the supplied workspace" loading="lazy"><div class="note-no">03 / MODELS WITH CLEAR BOUNDARIES</div><h2>${t('Know what your result means.','بدان نتیجه‌ات دقیقاً چه معنایی دارد.')}</h2><div class="table-wrap"><table><thead><tr><th>Experiment</th><th>What runs here</th><th>Boundary</th></tr></thead><tbody>${[['Circuit composer','Pure-state preparation + global depolarizing mixture','Classical browser simulation, 2–12 qubits'],['Grover / QAOA / Born machine','Gate-level statevector calculations','Small local registers; no hardware claims'],['Shor','Analytic period-finding histogram','Order is computed classically'],['Annealing','Classical Metropolis spin updates','Not quantum adiabatic evolution'],['Circuit knitting','Pauli density-matrix decomposition','Pedagogical reconstruction; no distributed cut execution'],['Open systems','Euler integration of Bloch/Lindblad equations','Numerical approximation; not a QuTiP backend'],['Evidence vault','Canonical JSON + SHA-256 integrity digest','Not a signature, theorem or hardware attestation']].map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></article><article class="note-card"><div class="note-no">04 / REPRODUCIBILITY</div><h2>${t('Same seed. Same measurement record.','بذر یکسان؛ سابقهٔ یکسان.')}</h2><p>${t('Exact probabilities depend on circuit parameters. Measurement counts also depend on shots and a seeded random generator. A fresh run picks a new seed unless you lock it. A saved record includes all three, and Replay compares the sampled counts.','احتمال دقیق به پارامترهای مدار بستگی دارد. شمارش اندازه‌گیری به تعداد شات و بذر هم وابسته است. بازپخش، شمارش‌ها را دوباره محاسبه و مقایسه می‌کند.')}</p><p style="margin-top:15px">${t('Storage is local to this browser. Export JSON for archival use; OpenQASM exports describe the ideal circuits and exclude display-only noise.','ذخیره‌سازی به همین مرورگر محدود است. برای بایگانی JSON بگیر؛ QASM مدار ایده‌آل را توصیف می‌کند.')}</p></article><article class="note-card"><div class="note-no">05 / THE NEXT CHAPTER</div><h2>${t('Follow the execution core.','مسیر هستهٔ اجرا را دنبال کن.')}</h2><p>${t('The repository also has separate proposals for a replayable twelve-qubit execution core and a chimera-run/v2 evidence export. They are linked for inspection; they are not merged into this browser runtime.','ریپو پیشنهادهای مستقلی برای هستهٔ اجرای قابل‌بازپخش و خروجی chimera-run/v2 دارد. این موارد برای بررسی لینک شده‌اند و جزئی از اجرای این سایت نیستند.')}</p><p style="margin-top:17px"><a href="https://github.com/aixaria0/Quantum001/pull/1" target="_blank" rel="noopener">Execution core · PR #1 ↗</a><br><a href="https://github.com/aixaria0/Quantum001/pull/2" target="_blank" rel="noopener">Evidence export · PR #2 ↗</a></p></article></div></div>`;}

let replayPending=null;
function render(){animationStop();result=null;activeId='';chrome();const [view,id]=route();try{$('#main').innerHTML=view==='overview'?overview():view==='library'?overview(true):view==='composer'?experiment('composer'):view==='lab'&&LABS.some(x=>x.id===id)?experiment(id):view==='evidence'?vault():view==='notes'?notes():`<div class="empty-state"><h1>${t('This state is outside our register.','این حالت در رجیستر ما نیست.')}</h1><p>${t('The requested experiment does not exist.','این آزمایش وجود ندارد.')}</p><a class="btn" href="#overview">${t('Return to the studio','بازگشت به استودیو')}</a></div>`;
 if($('#hero-canvas'))animationStop=orbital($('#hero-canvas'));if(activeId){if(replayPending&&replayPending.payload.experiment===activeId){const e=replayPending;replayPending=null;params={...e.payload.parameters};seed=e.payload.seed;shots=e.payload.shots||512;lockSeed=true;$('#parameter-fields').innerHTML=CONTROLS[activeId].map(field).join('');$('#seed').value=seed;$('#shots').value=shots;$('#lock-seed').checked=true;recompute();run(false);const matches=JSON.stringify(counts)===JSON.stringify(e.payload.counts);toast(matches?t('Replay matches the saved measurement record.','بازپخش با سابقهٔ ذخیره‌شده مطابقت دارد.'):t('Replay differs from the saved record. Inspect the model version.','بازپخش متفاوت است؛ نسخهٔ مدل را بررسی کن.'));}else drawResult();}
 }catch(e){$('#main').innerHTML=`<div class="empty-state"><h2>${t('The experiment needs a closer look.','آزمایش نیاز به بررسی دارد.')}</h2><p>${esc(e.message)}</p><a class="btn" href="#overview">${t('Back to the studio','بازگشت')}</a></div>`;}document.title=(view==='overview'?'Quantum001 — The Quantum Studio':(activeId?nameOf(activeId):view)+' · Quantum001');closeMobile();}
function recompute(){try{result=evaluate(activeId,params,seed);counts=null;drawResult();}catch(e){result=null;counts=null;animationStop();$('#visual-stage').innerHTML=`<div class="empty-state" style="margin:0;border:0"><h3>${t('Choose valid parameters','پارامتر معتبر انتخاب کن')}</h3><p>${esc(e.message)}</p></div>`;$('#metrics').innerHTML='';$('#tab-body').textContent=e.message;$('#model-scope').textContent=e.message;toast(e.message);}}
function run(showToast=true){if(!activeId||!result)return;if(!lockSeed){const a=new Uint32Array(1);crypto.getRandomValues(a);seed=a[0];$('#seed').value=seed;}else{const n=Number($('#seed').value);if(!Number.isInteger(n)||n<0||n>4294967295){toast(t('Use an integer seed between 0 and 4294967295.','بذر باید عدد صحیح بین صفر و ۴۲۹۴۹۶۷۲۹۵ باشد.'));return;}seed=n;}result=evaluate(activeId,params,seed);counts=result.probabilities?sample(result.probabilities,shots,seed):null;drawResult();if(counts){tab='measurements';renderTab();}if(showToast)toast(t('Experiment complete. The result is ready to inspect.','آزمایش تمام شد؛ نتیجه آمادهٔ بررسی است.'));}
function closeMobile(){$('#sidebar').classList.remove('open');$('#mobile-shade').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false');}
function search(){const d=$('#search-dialog');if(!d.open)d.showModal();$('#global-search').value='';searchResults('');$('#global-search').focus();}
function searchResults(q){const query=q.toLowerCase().trim(),items=[...LABS.map(l=>({id:'lab/'+l.id,title:nameOf(l.id),desc:CATEGORIES[l.id]+' '+l.kicker+' '+FA_TITLES[l.id]})),{id:'composer',title:nameOf('composer'),desc:'Bell GHZ 12 qubits مدار'},{id:'evidence',title:t('Evidence vault','گنجینهٔ شواهد'),desc:'SHA256 replay JSON شواهد'},{id:'notes',title:t('Field notes','یادداشت‌ها'),desc:'source models مستندات'}].filter(x=>(x.title+' '+x.desc).toLowerCase().includes(query));$('#search-results').innerHTML=items.length?items.map(x=>`<a class="search-result" href="#${x.id}"><span>${esc(x.title)}</span>${icon('arrow')}</a>`).join(''):`<p class="muted" style="padding:25px">${t('No matching experiments. Try “Grover”, “GHZ” or “noise”.','نتیجه‌ای پیدا نشد؛ «گروور»، GHZ یا noise را امتحان کن.')}</p>`;}

document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
 try{
 if(b.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');$('#mobile-shade').classList.toggle('open',open);b.setAttribute('aria-expanded',String(open));return;}
 if(b.id==='close-search'){$('#search-dialog').close();return;}
 if(b.closest('#search-results')){$('#search-dialog').close();if(b.hash===location.hash)render();return;}
 if(b.dataset.filter){filter=b.dataset.filter;$('#main').innerHTML=overview(route()[0]==='library');animationStop();if($('#hero-canvas'))animationStop=orbital($('#hero-canvas'));return;}
 if(b.dataset.tab){tab=b.dataset.tab;renderTab();return;}
 if(b.dataset.verify!==undefined){const valid=await verifyEvidence(entries[+b.dataset.verify]);toast(valid?t('Integrity verified. The payload matches its SHA-256 digest.','یکپارچگی تأیید شد؛ هش با داده‌ها مطابقت دارد.'):t('Integrity check failed. This record has changed.','بررسی هش ناموفق بود؛ سابقه تغییر کرده است.'));return;}
 if(b.dataset.download!==undefined){const entry=entries[+b.dataset.download];download(`quantum001-${entry.payload.experiment}-${entry.payload.seed}.json`,JSON.stringify(entry,null,2));return;}
 if(b.dataset.replay!==undefined){const entry=entries[+b.dataset.replay];if(!await verifyEvidence(entry)){toast(t('Replay refused: integrity check failed.','بازپخش رد شد: هش داده‌ها معتبر نیست.'));return;}replayPending=entry;setRoute(entry.payload.experiment==='composer'?'composer':'lab/'+entry.payload.experiment);return;}
 if(b.dataset.remove!==undefined){entries.splice(+b.dataset.remove,1);persist();render();return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='search'){search();return;}
 if(action==='language'){lang=lang==='en'?'fa':'en';persist();render();return;}
 if(action==='pause'){paused=!paused;b.innerHTML=icon(paused?'play':'pause');b.setAttribute('aria-pressed',String(paused));b.setAttribute('aria-label',paused?'Resume orbital animation':'Pause orbital animation');return;}
 if(action==='reset'){params=defaults(activeId);trainingHistory=[];$('#parameter-fields').innerHTML=CONTROLS[activeId].map(field).join('');$('#training-loss')?.replaceChildren();recompute();return;}
 if(action==='run'){run();return;}
 if(action==='optimize'){b.disabled=true;await new Promise(r=>setTimeout(r,30));const best=optimizeCut();params.gamma=best.gamma;params.beta=best.beta;$('#parameter-fields').innerHTML=CONTROLS[activeId].map(field).join('');recompute();b.disabled=false;toast(t('Angle sweep complete. Best grid point selected.','جست‌وجوی زاویه‌ها تمام شد؛ بهترین نقطه انتخاب شد.'));return;}
 if(action==='train'){b.disabled=true;await new Promise(r=>setTimeout(r,30));const trained=trainBorn(params);trainingHistory=trained.loss;params=trained.params;$('#parameter-fields').innerHTML=CONTROLS[activeId].map(field).join('');$('#training-loss').textContent=`KL ${trainingHistory[0].toFixed(4)} → ${trainingHistory.at(-1).toFixed(4)}`;recompute();b.disabled=false;toast(t('Training complete. The circuit parameters have learned.','آموزش تمام شد؛ پارامترهای مدار به‌روزرسانی شدند.'));return;}
 if(action==='save'){if(!result)return;b.disabled=true;const record=await evidence(result,shots);entries.unshift(record);entries=entries.slice(0,12);const saved=persist();b.disabled=false;chrome();toast(saved?t('Evidence saved. Inspect it in the Evidence vault.','شواهد ذخیره شد؛ در گنجینهٔ شواهد بررسی کن.'):t('Download this record to keep it.','برای نگه‌داری، این سابقه را دانلود کن.'));return;}
 if(action==='export-code'){download(`quantum001-${activeId}.${result.qasm?'qasm':'json'}`,result.qasm??JSON.stringify({model:result.kind,parameters:params,note:result.note},null,2),result.qasm?'text/plain':'application/json');return;}
 }catch(err){b.disabled=false;toast(err.message);}
});
document.addEventListener('input',e=>{const key=e.target.dataset.param;if(key){const c=CONTROLS[activeId].find(x=>x.key===key);params[key]=c.type==='select'&&typeof c.value==='string'?e.target.value:Number(e.target.value);if(activeId==='grover'&&key==='qubits'){params.marked=Math.min(params.marked,(1<<params.qubits)-1);const m=$('[data-param="marked"]');m.max=(1<<params.qubits)-1;m.value=params.marked;$('#out-marked').textContent=params.marked;}const out=$('#out-'+key);if(out)out.textContent=c.step<1?Number(params[key]).toFixed(2):params[key];recompute();}if(e.target.id==='global-search')searchResults(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='shots'){shots=Number(e.target.value);counts=null;renderTab();}if(e.target.id==='lock-seed')lockSeed=e.target.checked;if(e.target.id==='seed'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<=4294967295){seed=n;recompute();}else toast(t('Use a valid unsigned 32-bit seed.','یک بذر صحیح ۳۲ بیتی معتبر وارد کن.'));}});
document.addEventListener('submit',e=>{if(e.target.id!=='terminal-form')return;e.preventDefault();const input=$('#terminal-input'),raw=input.value.trim(),args=raw.toLowerCase().split(/\s+/),log=$('#terminal-output');if(!raw)return;let message='';try{if(args[0]==='help')message='bell · ghz [2|3|4|8|12] · product · noise <0..1> · help';else{if(args[0]==='bell'){params={...params,preset:'bell',noise:0};}else if(args[0]==='ghz'){const n=Number(args[1]??4);if(![2,3,4,8,12].includes(n))throw new Error('Choose 2, 3, 4, 8 or 12 qubits.');params={...params,preset:'ghz',qubits:n};}else if(args[0]==='product'){params={...params,preset:'product'};}else if(args[0]==='noise'){const p=Number(args[1]);if(!Number.isFinite(p)||p<0||p>1)throw new Error('Noise must be between 0 and 1.');params={...params,noise:p};}else throw new Error('Unknown command. Type help.');$('#parameter-fields').innerHTML=CONTROLS.composer.map(field).join('');recompute();run(false);message=`${result.qubits} qubits · F=${result.fidelity.toFixed(5)} · ${shots} shots · seed=${seed}`;}}catch(err){message=err.message;}log.insertAdjacentHTML('beforeend',`<br><span class="accent">› ${esc(raw)}</span><br>${esc(message)}`);log.scrollTop=log.scrollHeight;input.value='';});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();return;}if(e.key==='Escape')closeMobile();if($('#search-dialog').open&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=[...document.querySelectorAll('.search-result')],index=items.indexOf(document.activeElement),next=e.key==='ArrowDown'?index+1:index-1;items[(next+items.length)%items.length]?.focus();}if($('#search-dialog').open&&e.key==='Enter'&&document.activeElement===$('#global-search')){$('.search-result')?.click();}if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]')],index=tabs.indexOf(e.target),next=tabs[(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.click();next.focus();}});
$('#mobile-shade').addEventListener('click',closeMobile);$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});render();
